#pragma once
template<class Read> void corpusLiveCheck(juce::AudioProcessor* p,juce::AudioBuffer<float>& audio,juce::MidiBuffer& midi,Read value,const std::string& path){
 auto check=[](bool x,const std::string& why){if(!x)throw std::runtime_error("Live: "+why);};
 auto process=[&](){audio.clear();midi.clear();p->processBlock(audio,midi);};
 auto wait=[&](){for(int i=0;i<180000;++i){process();if(i%32==0)juce::MessageManager::getInstance()->runDispatchLoopUntil(1);if(i>100 && value("ready")>0 && value("pe_ready")>0 && value("pg_ready")>0 && value("pg_initializing")==0 && value("auto_settings_pending")==0 && value("rebuild_request")==0 && value("cg_stage")==0)return;std::this_thread::sleep_for(std::chrono::milliseconds(1));}throw std::runtime_error("Live prepare timed out");};
 auto heap=[&](const char* name,int count){std::vector<double> x(count);check(za_native_gfx_heap_copy(p,name,x.data(),count)==count,"heap copy");return x;};
 auto command=[&](int op,int arg){int serial=(int(value("cmd_seen")/1048576)+1)%16;za_test_gfx_button(p,24,serial*1048576+arg*16+op);process();};
 check(p->getParameters().size()==249,"248 controls + oversampling");check(corpusGet(p,73)==1 && corpusGet(p,245)==1,"new pitch and quiet defaults");
 {std::unique_ptr<juce::AudioProcessor> q(createPluginFilter());check(corpusGet(q.get(),73)==1,"fresh Coherent pitch");juce::MemoryBlock old;juce::File oldFile=juce::File(juce::String::fromUTF8(path.c_str())).getParentDirectory().getChildFile("v220-state.bin");check(oldFile.loadFileAsData(old),"old preset load");q->setStateInformation(old.getData(),int(old.getSize()));check(corpusGet(q.get(),73)==0,"old explicit Tape changed");check(std::abs(corpusGet(q.get(),244)-1.2)<.01,"old limit state changed");check(corpusGet(q.get(),40)==52 && corpusGet(q.get(),16)==159 && corpusGet(q.get(),246)==0 && corpusGet(q.get(),248)==0,"old map/filter range changed");auto xml=juce::AudioProcessor::getXmlFromBinary(old.getData(),int(old.getSize()));auto tree=juce::ValueTree::fromXml(*xml);auto node=tree.getChildWithProperty("id","slider73");tree.removeChild(node,nullptr);juce::MemoryBlock legacy;auto lx=tree.createXml();juce::AudioProcessor::copyXmlToBinary(*lx,legacy);corpusSet(q.get(),73,1);q->setStateInformation(legacy.getData(),int(legacy.getSize()));check(corpusGet(q.get(),73)==0,"missing legacy pitch did not retain Tape");}
 std::cout<<"LIVE actual v2.2 preset:old limit units retained, editor in ms; explicit/missing Tape, old ECPE map/filter preserved; fresh Coherent pitch\n";
 corpusSet(p,242,2);wait();int n=int(value("grain_count"));auto g=heap("grain_base",n*64);auto bins=heap("desc_res_counts",864);double lengthSupport=0;for(int i=848;i<864;++i)lengthSupport+=bins[i];check(lengthSupport>0,"Length retrieval missing");auto ranges=heap("desc_value_range",162);check(ranges[16*3+2]>0 && ranges[16*3+1]>=ranges[16*3] && ranges[16*3+1]-ranges[16*3]<.8,"centroid range cache");check(ranges[53*3+2]==n,"Length range cache");std::cout<<"LIVE actual centroid extent="<<ranges[48]<<".."<<ranges[49]<<" supported="<<ranges[50]<<std::endl;
 for(auto [id,x]:std::vector<std::pair<int,float>>{{10,0},{25,4000},{76,0},{8,0},{56,0},{12,1},{45,0},{81,0},{246,0},{247,0},{248,0}})corpusSet(p,id,x);process();
 auto gap=[&](int id){auto* z=g.data()+id*64;return z[62]*z[63]*(.25+.75*std::min(1.,z[3]/z[4]/.35));};std::ofstream csv(path);csv<<"test,setting,records,near_silent_records,near_silent_source_seconds,mean_value\n";int bad[2]{};
 for(int policy:{0,1}){corpusSet(p,245,float(policy));int count=0;double quietSeconds=0;for(int note=0;note<16;++note){corpusSet(p,11,float(12345+note*104729));process();for(int b=0;b<850;++b){audio.clear();midi.clear();if(!b)midi.addEvent(juce::MidiMessage::noteOn(1,60,juce::uint8(100)),0);p->processBlock(audio,midi);check(std::isfinite(audio.getMagnitude(0,audio.getNumSamples())),"nonfinite quiet test");}int nr=int(value("record_n"));auto r=heap("record_base",nr*20);for(int i=0;i<nr;++i){int id=int(r[i*20]);++count;if(gap(id)>=.4){++bad[policy];quietSeconds+=g[id*64+3]/g[id*64+4];}}}csv<<"quiet,"<<policy<<','<<count<<','<<bad[policy]<<','<<quietSeconds<<",0\n";std::cout<<"LIVE quiet policy="<<policy<<" near_silent="<<bad[policy]<<'/'<<count<<" source_seconds="<<quietSeconds<<std::endl;}
 check(bad[0]>0 && bad[1]<bad[0],"default quiet policy did not improve source selection");check(bad[1]==0,"quiet alternative retrieval failed on supplied source");
 // The new descriptor is an ordinary Target lane; long/short requests must
 // move actual selected durations, not only the display.
 for(int i=0;i<12;++i)corpusSet(p,86+i*13,0);corpusSet(p,86,3125);corpusSet(p,87,1);corpusSet(p,81,2);corpusSet(p,2,0);std::vector<double> means;
 for(int target:{6,120}){for(int j=0;j<11;++j)corpusSet(p,88+j,float(target+target*128+(j<10?target*16384:0)));process();for(int b=0;b<850;++b){audio.clear();midi.clear();if(!b)midi.addEvent(juce::MidiMessage::noteOn(1,60,juce::uint8(100)),0);p->processBlock(audio,midi);}int nr=int(value("record_n"));auto r=heap("record_base",nr*20);double sum=0;for(int i=0;i<nr;++i){int id=int(r[i*20]);sum+=g[id*64+3]/g[id*64+4];}check(nr>0,"Length empty plan");means.push_back(sum/nr);csv<<"Length,"<<target<<','<<nr<<",0,0,"<<means.back()<<'\n';}
 check(means[1]>means[0]*1.5,"Length target did not change actual durations");std::cout<<"LIVE Length short/long target actual mean_seconds="<<means[0]<<"/"<<means[1]<<std::endl;
 corpusSet(p,246,1);corpusSet(p,248,3);process();juce::MemoryBlock state;p->getStateInformation(state);corpusSet(p,246,0);corpusSet(p,248,0);p->setStateInformation(state.getData(),int(state.getSize()));wait();check(corpusGet(p,246)==1 && corpusGet(p,248)==3,"Length map/filter persistence");corpusSet(p,248,0);corpusSet(p,246,0);
 // Gated Event must keep traversing beyond its first pass. Explicit Once is
 // still tested in the native clock suite; no sounding passage is shortened.
 for(auto [id,x]:std::vector<std::pair<int,float>>{{10,1},{82,0},{83,2},{84,0},{85,-1},{86,3073},{87,1},{2,0},{81,2},{73,0}})corpusSet(p,id,x);for(int j=0;j<11;++j){int packed=0;for(int k=0;k<3;++k)if(j*3+k<32)packed+=int(std::round((.1+.8*(j*3+k)/31)*126))<<(k*7);corpusSet(p,88+j,float(packed));}process();
 for(int style:{1,2}){corpusSet(p,242,float(style));wait();int nnow=int(value("grain_count"));auto gg=heap("grain_base",nnow*64);double minAfter=1,maxAfter=0;int lateChoices=0;std::vector<float> rendered;
  for(int b=0;b<1800;++b){audio.clear();midi.clear();if(!b)midi.addEvent(juce::MidiMessage::noteOn(1,60,juce::uint8(100)),0);if(b==1500)midi.addEvent(juce::MidiMessage::noteOff(1,60),0);p->processBlock(audio,midi);if(b>750 && b<1500){auto rt=heap("traj_runtime_base",64);minAfter=std::min(minAfter,rt[8]);maxAfter=std::max(maxAfter,rt[8]);}for(int i=0;i<audio.getNumSamples();++i)for(int c=0;c<2;++c)rendered.push_back(audio.getSample(c,i));}
  int nr=int(value("record_n"));auto r=heap("record_base",nr*20);for(int i=0;i<nr;++i)lateChoices+=r[i*20+2]>4*48000;check(lateChoices>0 && maxAfter-minAfter>.3,"Gated Event stopped moving after first pass");check(value("voice_list_n")==0 && value("event_count")==0,"Gated NoteOff did not release");
  corpusSet(p,81,0);command(4,0);double error=0;size_t at=0;for(int b=0;b<1802;++b){if(b)process();for(int i=0;i<audio.getNumSamples();++i)for(int c=0;c<2;++c){constexpr size_t pad=144*2;double expected=at<pad || at-pad>=rendered.size()?0:rendered[at-pad];error=std::max(error,std::abs(double(audio.getSample(c,i))-expected));++at;}}check(error<1e-6,"Gated REPEAT waveform changed");corpusSet(p,81,2);std::cout<<"LIVE Gated style="<<style<<" late request_range="<<minAfter<<".."<<maxAfter<<" late_choices="<<lateChoices<<" NoteOff released REPEAT_error="<<error<<std::endl;
 }
 uint32_t dsp=0,gfx=0;za_native_gfx_faults(p,&dsp,&gfx);check(!dsp&&!gfx&&value("invalid_audio")==0 && value("pe_read_errors")==0,"runtime faults");std::cout<<"LIVE quiet/Length/Gated/preset checks passed; faults0/0\n";
}
